function dp($pos, $prevY, $humps, $valleys, $lastDir, $n, $t, &$memo) {
    if ($pos > $n) {
        return ($humps == $t && $valleys == $t - 1) ? 1 : 0;
    }
    $key = "$pos|$prevY|$humps|$valleys|$lastDir";
    if (isset($memo[$key])) {
        return $memo[$key];
    }
    $count = 0;
    for ($y = 1; $y <= 4; $y++) {
