            $count += dp($pos + 1, $y, 0, 0, 0, $n, $t, $memo);
        } else {
            $dir = ($y > $prevY) ? 1 : (($y < $prevY) ? -1 : 0);
            if ($dir == 0) continue;
            $newHumps = $humps;
            $newValleys = $valleys;
            if ($pos >= 3) {
                if ($lastDir == 1 && $dir == -1) {
                    $newHumps++;
                } else if ($lastDir == -1 && $dir == 1) {
                    $newValleys++;
                }
            }
            $count += dp($pos + 1, $y, $newHumps, $newValleys, $dir, $n, $t, $memo);
