function countCamels($n, $t) {
    $memo = [];

    function dp($i, $prevY, $prevPrevY, $humps, $valleys, $memo, $n, $t) {
        if ($i == $n) {
            return ($humps == $t && $valleys == $t - 1) ? 1 : 0;
        }

        $key = "$i|$prevY|$prevPrevY|$humps|$valleys";
        if (isset($memo[$key])) return $memo[$key];

        $total = 0;
        for ($y = 1; $y <= 4; $y++) {
            if ($y == $prevY) continue;

            $newHumps = $humps;
            $newValleys = $valleys;

            if ($i >= 2) {
                if ($prevPrevY < $prevY && $prevY > $y) {
                    $newHumps++;
                }
                if ($prevPrevY > $prevY && $prevY < $y) {
                    $newValleys++;
                }
            }

            if ($newHumps > $t || $newValleys > $t - 1) continue;

            $total += dp($i + 1, $y, $prevY, $newHumps, $newValleys, $memo, $n, $t);
        }

        return $memo[$key] = $total;
    }

    return dp(0, 0, 0, 0, 0, $memo, $n, $t);
}

