    $line = trim(fgets(STDIN));
    list($n, $t) = array_map('intval', explode(' ', $line));

    $memo = [];

    function dp($pos, $prevY, $prevPrevY, $humps, $valleys, $lastDir, $n, $t, &$memo) {
        if ($pos === $n) {
            return ($humps === $t && $valleys === $t - 1) ? 1 : 0;
        }

        $key = "$pos|$prevY|$prevPrevY|$humps|$valleys|$lastDir";
        if (isset($memo[$key])) {
            return $memo[$key];
        }

        $total = 0;
        for ($y = 1; $y <= 4; $y++) {
            if ($pos >= 2) {
                if ($y === $prevY) {
                    continue;
                }
                $dir = ($y > $prevY) ? 1 : -1;
                if ($dir === $lastDir) {
                    continue;
                }
                $newHumps = $humps;
                $newValleys = $valleys;
                if ($lastDir === 1 && $dir === -1) {
                    $newHumps++;
                } else if ($lastDir === -1 && $dir === 1) {
                    $newValleys++;
                }
                if ($newHumps > $t || $newValleys > $t - 1) {
                    continue;
                }
                $total += dp($pos + 1, $y, $prevY, $newHumps, $newValleys, $dir, $n, $t, $memo);
            } else {
                if ($pos === 1) {
                    if ($y === $prevY) {
                        continue;
                    }
                    $dir = ($y > $prevY) ? 1 : -1;
                    $total += dp($pos + 1, $y, $prevY, 0, 0, $dir, $n, $t, $memo);
                } else {
                    $total += dp($pos + 1, $y, 0, 0, 0, 0, $n, $t, $memo);
                }
            }
        }

        $memo[$key] = $total;
        return $total;
    }

